// ME2 backfill of purchases per attribution window (migration 256). MANUAL RUN ONLY.
// Emits 12-day chunks from each client's first ad-insights day to yesterday. Idempotent:
// raw is append-only and stg.stg_meta_ad_attribution_windows keeps the latest ingest,
// so a re-run (for example after a failed chunk) only adds rows.
const CLIENTS    = [];   // empty = every active Meta client; e.g. ['dobias','ethia','manami','venev']
const CHUNK_DAYS = 12;   // the size the live workflow uses
const ymd = d => d.toISOString().slice(0, 10);
const yesterday = new Date();
yesterday.setUTCDate(yesterday.getUTCDate() - 1);

return $input.all().flatMap(item => {
  const c = item.json;
  if (CLIENTS.length && !CLIENTS.includes(c.client_id)) return [];
  if (!c.min_date) return [];
  const start = new Date(c.min_date + 'T00:00:00Z');
  const out = [];
  for (let until = new Date(yesterday); until >= start; until.setUTCDate(until.getUTCDate() - CHUNK_DAYS)) {
    const since = new Date(until);
    since.setUTCDate(since.getUTCDate() - (CHUNK_DAYS - 1));
    const s = since < start ? start : since;
    out.push({ json: {
      client_id: c.client_id,
      slug: c.slug,
      currency: c.currency,
      mode: 'backfill_me2',
      chunk_label: `me2_${ymd(s)}_${ymd(until)}`,
      time_range: `{"since":"${ymd(s)}","until":"${ymd(until)}"}`
    }});
  }
  return out;
});

const decode = b64 => Buffer.from(b64, 'base64').toString('utf8').trim();
const accessToken = decode($('Get access_token').first().json.payload.data);
const adAccountId = decode($('Get ad_account_id').first().json.payload.data);
const item = $('Loop over plan').item.json;

return [{ json: {
  client_id: item.client_id,
  slug: item.slug,
  currency: item.currency,
  mode: item.mode,
  chunk_label: item.chunk_label,
  time_range: item.time_range,
  access_token: accessToken,
  ad_account_id: adAccountId,
  api_version: 'v22.0'
}}];

// ME2 (migration 256): purchases per attribution window, one row per ad-day.
// Requested with action_attribution_windows=["7d_click","1d_view","1d_ev"], so every
// actions[] / action_values[] entry carries one key per window next to `value`.
// The legacy columns of raw_meta_ad_insights (purchases, purchase_value) are NOT taken
// from this request: they stay on each ad set's own attribution setting.
const ctx = $('Decode secrets').first().json;
const WINDOWS = '7d_click,1d_view,1d_ev';
const INGESTED_AT = new Date().toISOString();
const num = v => (v === null || v === undefined || v === '' ? null : Number(v));
// Same action type preference as the legacy columns: omni_purchase, else purchase.
const entry = arr => {
  if (!Array.isArray(arr)) return null;
  return arr.find(a => a.action_type === 'omni_purchase')
      ?? arr.find(a => a.action_type === 'purchase')
      ?? null;
};
// Entry present but window key absent: 0 for that window. No entry: NULL (no purchase action).
const win = (e, w) => (e === null ? null : (e[w] === undefined ? 0 : num(e[w])));

const all = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.data)) {
    for (const r of j.data) all.push(r);
  } else if (j.ad_id) {
    all.push(j);
  }
}

return all.map(r => {
  const a = entry(r.actions);
  const v = entry(r.action_values);
  return { json: {
    client_id: ctx.client_id,
    ingested_at: INGESTED_AT,
    ingest_source: ctx.mode === 'backfill_me2' ? 'backfill_me2' : 'cron',
    ad_account_id: ctx.ad_account_id,
    campaign_id: String(r.campaign_id ?? ''),
    adset_id:    String(r.adset_id    ?? ''),
    ad_id:       String(r.ad_id),
    date_start: r.date_start,
    date_stop:  r.date_stop,
    attribution_windows: WINDOWS,
    purchases_7d_click:           win(a, '7d_click'),
    purchase_value_7d_click:      win(v, '7d_click'),
    purchases_1d_view:            win(a, '1d_view'),
    purchase_value_1d_view:       win(v, '1d_view'),
    purchases_1d_ev:              win(a, '1d_ev'),
    purchase_value_1d_ev:         win(v, '1d_ev'),
    purchases_windows_value:      a === null ? null : num(a.value),
    purchase_value_windows_value: v === null ? null : num(v.value),
    actions:       JSON.stringify(r.actions ?? []),
    action_values: JSON.stringify(r.action_values ?? [])
  }};
});
